//! Every supported format decodes to the right length and content; damaged
//! files produce errors, never panics.
//!
//! The fixtures are generated by `tests/fixtures/make_fixtures.sh` from a
//! known signal: 440 Hz at amplitude 0.5 on the left, 880 Hz at 0.5 on the
//! right (see `make_sources.py`).

mod common;

use common::{Rng, Scratch, fixture, fixtures, tone_amplitude};
use splitsound_core::ErrorCode;
use splitsound_core::decode::{DecodeLimits, decode_file, decode_native};
use splitsound_core::progress::{CancelFlag, NoProgress};

const RATE: u32 = 44_100;

struct Case {
    file: &'static str,
    codec: &'static str,
    src_rate: u32,
    src_channels: u16,
    /// Expected length at 44.1 kHz and how far off it may be.
    frames: usize,
    frames_slack: usize,
    /// Lossy codecs get a looser amplitude tolerance.
    amp_tol: f64,
}

const CASES: &[Case] = &[
    Case {
        file: "tone_s16.wav",
        codec: "WAV",
        src_rate: 44_100,
        src_channels: 2,
        frames: 22_050,
        frames_slack: 0,
        amp_tol: 0.002,
    },
    Case {
        file: "tone_s24_48k.wav",
        codec: "WAV",
        src_rate: 48_000,
        src_channels: 2,
        frames: 22_050,
        frames_slack: 0,
        amp_tol: 0.002,
    },
    Case {
        file: "tone.aiff",
        codec: "AIFF",
        src_rate: 44_100,
        src_channels: 2,
        frames: 22_050,
        frames_slack: 0,
        amp_tol: 0.002,
    },
    Case {
        file: "tone.flac",
        codec: "FLAC",
        src_rate: 44_100,
        src_channels: 2,
        frames: 44_100,
        frames_slack: 0,
        amp_tol: 0.002,
    },
    Case {
        file: "tone_alac.m4a",
        codec: "ALAC",
        src_rate: 44_100,
        src_channels: 2,
        frames: 44_100,
        frames_slack: 0,
        amp_tol: 0.002,
    },
    Case {
        file: "tone_alac.caf",
        codec: "ALAC",
        src_rate: 44_100,
        src_channels: 2,
        frames: 22_050,
        frames_slack: 0,
        amp_tol: 0.002,
    },
    // LAME attenuates by about 5% (ffmpeg's own decode of this file
    // measures 0.4748), so the tolerance has to cover that.
    Case {
        file: "tone.mp3",
        codec: "MP3",
        src_rate: 44_100,
        src_channels: 2,
        frames: 44_100,
        frames_slack: 0,
        amp_tol: 0.03,
    },
    Case {
        file: "tone.ogg",
        codec: "Vorbis",
        src_rate: 44_100,
        src_channels: 2,
        frames: 44_100,
        frames_slack: 0,
        amp_tol: 0.02,
    },
    Case {
        file: "tone.opus",
        codec: "Opus",
        src_rate: 48_000,
        src_channels: 2,
        frames: 44_100,
        frames_slack: 0,
        amp_tol: 0.02,
    },
    // AAC keeps its encoder priming (1024 frames) and padding: Symphonia
    // does not apply MP4 edit lists. See README "Known limitations".
    Case {
        file: "tone.m4a",
        codec: "AAC",
        src_rate: 44_100,
        src_channels: 2,
        frames: 44_100,
        frames_slack: 2_200,
        amp_tol: 0.02,
    },
    Case {
        file: "tone.aac",
        codec: "AAC",
        src_rate: 44_100,
        src_channels: 2,
        frames: 44_100,
        frames_slack: 2_200,
        amp_tol: 0.02,
    },
];

#[test]
fn every_format_decodes_to_the_right_length_and_content() {
    for case in CASES {
        let path = fixture(&format!("audio/{}", case.file));
        let t = decode_file(&path, RATE, &DecodeLimits::default(), &NoProgress)
            .unwrap_or_else(|e| panic!("{}: {} ({:?})", case.file, e, e.detail()));
        assert_eq!(t.sample_rate, RATE, "{}", case.file);
        assert_eq!(t.info.codec, case.codec, "{}", case.file);
        assert_eq!(t.info.sample_rate, case.src_rate, "{}", case.file);
        assert_eq!(t.info.channels, case.src_channels, "{}", case.file);
        assert_eq!(t.audio.left.len(), t.audio.right.len());
        let n = t.audio.len();
        assert!(
            n >= case.frames && n <= case.frames + case.frames_slack,
            "{}: {} frames, expected {}..={}",
            case.file,
            n,
            case.frames,
            case.frames + case.frames_slack
        );
        assert!((t.info.duration_sec - n as f64 / 44_100.0).abs() < 1e-9);
        assert_eq!(
            t.info.file_size_bytes,
            std::fs::metadata(&path).unwrap().len()
        );
        assert!(t.info.bitrate_kbps.unwrap() > 8, "{}", case.file);
        // Content: 440 Hz left, 880 Hz right, 0.5 each, and no crosstalk.
        let edge = 4_000;
        let l440 = tone_amplitude(&t.audio.left, 440.0, RATE, edge);
        let r880 = tone_amplitude(&t.audio.right, 880.0, RATE, edge);
        let l880 = tone_amplitude(&t.audio.left, 880.0, RATE, edge);
        let r440 = tone_amplitude(&t.audio.right, 440.0, RATE, edge);
        assert!(
            (l440 - 0.5).abs() < case.amp_tol,
            "{}: L440 = {l440}",
            case.file
        );
        assert!(
            (r880 - 0.5).abs() < case.amp_tol,
            "{}: R880 = {r880}",
            case.file
        );
        assert!(
            l880 < case.amp_tol && r440 < case.amp_tol,
            "{}: crosstalk {l880} {r440}",
            case.file
        );
        assert!(
            t.audio
                .left
                .iter()
                .chain(&t.audio.right)
                .all(|v| v.is_finite() && v.abs() <= 1.0)
        );
    }
}

#[test]
fn mono_becomes_dual_mono() {
    // LAME attenuates by about 5% at this bitrate (ffmpeg's own decode of
    // the fixture measures 0.4748), hence the second expected level.
    for (file, codec, level, tol) in [
        ("tone_f32_mono.wav", "WAV", 0.5, 0.002),
        ("tone_mono.mp3", "MP3", 0.4748, 0.005),
    ] {
        let t = decode_file(
            &fixture(&format!("audio/{file}")),
            RATE,
            &DecodeLimits::default(),
            &NoProgress,
        )
        .unwrap();
        assert_eq!(t.info.channels, 1, "{file}");
        assert_eq!(t.info.codec, codec);
        assert_eq!(t.audio.left, t.audio.right, "{file}: channels differ");
        let a = tone_amplitude(&t.audio.left, 440.0, RATE, 2_000);
        assert!((a - level).abs() < tol, "{file}: {a}");
    }
}

#[test]
fn surround_is_downmixed() {
    // 5.1 FLAC: FL 440, FR 880, FC 1320, LFE 60, BL 220, BR 330, each 0.25.
    let t = decode_file(
        &fixture("audio/tone_51.flac"),
        RATE,
        &DecodeLimits::default(),
        &NoProgress,
    )
    .unwrap();
    assert_eq!(t.info.channels, 6);
    assert_eq!(t.audio.len(), 22_050);
    let h = std::f64::consts::FRAC_1_SQRT_2;
    let norm = 1.0 / (1.0 + 2.0 * h);
    let amp = |ch: &[f32], f: f64| tone_amplitude(ch, f, RATE, 2_000);
    let tol = 0.003;
    assert!(
        (amp(&t.audio.left, 440.0) - 0.25 * norm).abs() < tol,
        "front left"
    );
    assert!(
        (amp(&t.audio.right, 880.0) - 0.25 * norm).abs() < tol,
        "front right"
    );
    assert!(
        (amp(&t.audio.left, 1320.0) - 0.25 * h * norm).abs() < tol,
        "centre in left"
    );
    assert!(
        (amp(&t.audio.right, 1320.0) - 0.25 * h * norm).abs() < tol,
        "centre in right"
    );
    assert!(
        (amp(&t.audio.left, 220.0) - 0.25 * h * norm).abs() < tol,
        "back left"
    );
    assert!(
        (amp(&t.audio.right, 330.0) - 0.25 * h * norm).abs() < tol,
        "back right"
    );
    assert!(
        amp(&t.audio.left, 60.0) < tol && amp(&t.audio.right, 60.0) < tol,
        "LFE dropped"
    );
    assert!(amp(&t.audio.right, 440.0) < tol && amp(&t.audio.left, 880.0) < tol);
    assert!(amp(&t.audio.right, 220.0) < tol && amp(&t.audio.left, 330.0) < tol);

    // The same file is refused when the caller allows fewer channels.
    let limits = DecodeLimits {
        max_channels: 2,
        ..DecodeLimits::default()
    };
    let e = decode_file(&fixture("audio/tone_51.flac"), RATE, &limits, &NoProgress).unwrap_err();
    assert_eq!(e.code(), ErrorCode::UnsupportedFormat);
}

#[test]
fn resamples_to_the_requested_rate() {
    let t = decode_file(
        &fixture("audio/tone.flac"),
        32_000,
        &DecodeLimits::default(),
        &NoProgress,
    )
    .unwrap();
    assert_eq!(t.sample_rate, 32_000);
    assert_eq!(t.audio.len(), 32_000);
    assert!((tone_amplitude(&t.audio.left, 440.0, 32_000, 3_000) - 0.5).abs() < 0.002);
    assert!((tone_amplitude(&t.audio.right, 880.0, 32_000, 3_000) - 0.5).abs() < 0.002);
}

#[test]
fn tags_and_cover_art() {
    for (file, has_art) in [
        ("tagged.mp3", true),
        ("tagged.flac", true),
        ("tagged.m4a", true),
        ("tagged.opus", false),
        ("tagged.ogg", false),
    ] {
        let t = decode_file(
            &fixture(&format!("audio/{file}")),
            RATE,
            &DecodeLimits::default(),
            &NoProgress,
        )
        .unwrap_or_else(|e| panic!("{file}: {e}"));
        assert_eq!(t.info.title.as_deref(), Some("Fixture Title"), "{file}");
        assert_eq!(t.info.artist.as_deref(), Some("Fixture Artist"), "{file}");
        assert_eq!(t.info.album.as_deref(), Some("Fixture Album"), "{file}");
        assert_eq!(t.info.has_artwork, has_art, "{file}");
        assert_eq!(t.artwork.is_some(), has_art, "{file}");
        if let Some(art) = &t.artwork {
            assert_eq!(art.media_type, "image/png", "{file}");
            assert!(art.data.starts_with(&[0x89, b'P', b'N', b'G']), "{file}");
        }
    }
    // Untagged files report no tags rather than empty strings.
    let t = decode_file(
        &fixture("audio/tone.flac"),
        RATE,
        &DecodeLimits::default(),
        &NoProgress,
    )
    .unwrap();
    assert_eq!(
        (t.info.title, t.info.artist, t.info.album),
        (None, None, None)
    );
    assert!(t.artwork.is_none() && !t.info.has_artwork);
    // A picture bigger than the limit is skipped, not an error.
    let limits = DecodeLimits {
        max_artwork_bytes: 16,
        ..DecodeLimits::default()
    };
    let t = decode_file(&fixture("audio/tagged.flac"), RATE, &limits, &NoProgress).unwrap();
    assert!(t.artwork.is_none());
    assert_eq!(t.info.title.as_deref(), Some("Fixture Title"));
}

#[test]
fn limits_are_enforced() {
    // Duration cap: a 1 s file against a 0 s cap.
    let limits = DecodeLimits {
        max_duration_sec: 0,
        ..DecodeLimits::default()
    };
    for file in [
        "tone.flac",
        "tone.mp3",
        "tone.ogg",
        "tone.opus",
        "tone.aac",
        "tone_s16.wav",
    ] {
        let e = decode_file(
            &fixture(&format!("audio/{file}")),
            RATE,
            &limits,
            &NoProgress,
        )
        .unwrap_err();
        assert_eq!(e.code(), ErrorCode::DecodeFailed, "{file}");
        assert!(
            e.message().contains("longer than"),
            "{file}: {}",
            e.message()
        );
    }
}

#[test]
fn cancellation_stops_the_decode() {
    let flag = CancelFlag::new();
    flag.cancel();
    let e = decode_file(
        &fixture("audio/tone.flac"),
        RATE,
        &DecodeLimits::default(),
        &flag,
    )
    .unwrap_err();
    assert_eq!(e.code(), ErrorCode::Cancelled);
}

#[test]
fn things_that_are_not_audio() {
    let dir = Scratch::new("notaudio");
    let missing = dir.path().join("nope.mp3");
    assert_eq!(
        decode_file(&missing, RATE, &DecodeLimits::default(), &NoProgress)
            .unwrap_err()
            .code(),
        ErrorCode::FileNotFound
    );
    assert_eq!(
        decode_file(dir.path(), RATE, &DecodeLimits::default(), &NoProgress)
            .unwrap_err()
            .code(),
        ErrorCode::UnsupportedFormat
    );
    let cases: [(&str, &[u8]); 5] = [
        ("empty.mp3", b""),
        (
            "text.wav",
            b"hello, this is a text file pretending to be audio\n",
        ),
        (
            "page.flac",
            b"<!doctype html><html><body>not audio</body></html>",
        ),
        (
            "zip.m4a",
            b"PK\x03\x04\x14\x00\x00\x00\x08\x00 some zip-looking bytes follow here ......",
        ),
        ("zeros.ogg", &[0u8; 4096]),
    ];
    for (name, bytes) in cases {
        let p = dir.path().join(name);
        std::fs::write(&p, bytes).unwrap();
        let e = decode_file(&p, RATE, &DecodeLimits::default(), &NoProgress).unwrap_err();
        assert_eq!(e.code(), ErrorCode::UnsupportedFormat, "{name}: {e}");
    }
}

#[test]
fn committed_damaged_files_are_errors() {
    for entry in std::fs::read_dir(fixtures().join("corrupt")).unwrap() {
        let path = entry.unwrap().path();
        let e = decode_file(&path, RATE, &DecodeLimits::default(), &NoProgress)
            .err()
            .unwrap_or_else(|| panic!("{} decoded without error", path.display()));
        assert_eq!(e.code(), ErrorCode::DecodeFailed, "{}: {e}", path.display());
        assert!(!e.message().is_empty());
        // decode_native follows the same rules.
        assert!(decode_native(&path, &DecodeLimits::default(), &NoProgress).is_err());
    }
}

/// Truncates every fixture at many points and flips random bytes in it.
/// Whatever happens, the decoder must return (never panic, never hang) and
/// anything it does return must be sane.
#[test]
fn truncated_and_corrupted_variants_never_panic() {
    let dir = Scratch::new("mutations");
    let mut rng = Rng(0xC0FF_EE12_3456_789A);
    let mut files: Vec<_> = std::fs::read_dir(fixtures().join("audio"))
        .unwrap()
        .chain(std::fs::read_dir(fixtures().join("opus")).unwrap())
        .map(|e| e.unwrap().path())
        .filter(|p| {
            p.extension()
                .is_some_and(|e| e != "flac" || !p.to_string_lossy().contains(".ref."))
        })
        .collect();
    files.sort();
    let (mut ok, mut err) = (0usize, 0usize);
    for path in &files {
        let data = std::fs::read(path).unwrap();
        let ext = path.extension().unwrap().to_str().unwrap();
        let mut variants: Vec<Vec<u8>> = Vec::new();
        // Truncations: header-only sizes and a spread through the file.
        for keep in [1usize, 4, 12, 27, 44, 100, 512] {
            variants.push(data[..keep.min(data.len())].to_vec());
        }
        for tenth in 1..10 {
            variants.push(data[..data.len() * tenth / 10].to_vec());
        }
        variants.push(data[..data.len() - 1].to_vec());
        // Byte flips, in the header and anywhere.
        for round in 0..24 {
            let mut d = data.clone();
            let flips = 1 + rng.below(4);
            for _ in 0..flips {
                let limit = if round % 2 == 0 {
                    d.len().min(256)
                } else {
                    d.len()
                };
                let at = rng.below(limit);
                d[at] ^= 1 << rng.below(8);
            }
            variants.push(d);
        }
        // Whole-byte garbage runs and a zeroed block.
        for _ in 0..6 {
            let mut d = data.clone();
            let at = rng.below(d.len());
            let len = (1 + rng.below(64)).min(d.len() - at);
            for b in &mut d[at..at + len] {
                *b = rng.next() as u8;
            }
            variants.push(d);
        }
        let mut d = data.clone();
        let mid = d.len() / 2;
        let end = (mid + 512).min(d.len());
        d[mid..end].fill(0);
        variants.push(d);

        for (i, bytes) in variants.iter().enumerate() {
            let p = dir.path().join(format!("v{i}.{ext}"));
            std::fs::write(&p, bytes).unwrap();
            match decode_file(&p, RATE, &DecodeLimits::default(), &NoProgress) {
                Ok(t) => {
                    ok += 1;
                    assert_eq!(t.audio.left.len(), t.audio.right.len());
                    assert!(!t.audio.is_empty());
                    // Bounded by the default two hour cap, in practice tiny.
                    assert!(
                        t.audio.len() < 44_100 * 30,
                        "{}: variant {i} grew to {} frames",
                        path.display(),
                        t.audio.len()
                    );
                    assert!(
                        t.audio
                            .left
                            .iter()
                            .chain(&t.audio.right)
                            .all(|v| v.is_finite())
                    );
                }
                Err(e) => {
                    err += 1;
                    assert!(
                        matches!(
                            e.code(),
                            ErrorCode::DecodeFailed | ErrorCode::UnsupportedFormat
                        ),
                        "{}: variant {i}: unexpected {:?} {e}",
                        path.display(),
                        e.code()
                    );
                }
            }
        }
        // Every strict truncation (to at most 90%) of a file whose container
        // records its exact length must be an error.
        let exact = matches!(ext, "wav" | "aiff" | "flac" | "m4a");
        if exact {
            for tenth in 1..10 {
                let p = dir.path().join(format!("cut{tenth}.{ext}"));
                std::fs::write(&p, &data[..data.len() * tenth / 10]).unwrap();
                assert!(
                    decode_file(&p, RATE, &DecodeLimits::default(), &NoProgress).is_err(),
                    "{} cut to {tenth}0% decoded without error",
                    path.display()
                );
            }
        }
    }
    println!(
        "mutations: {} files, {ok} variants decoded, {err} rejected",
        files.len()
    );
    assert!(
        err > ok,
        "most mutations should be rejected ({ok} ok, {err} err)"
    );
}
